import{_ as i,o as n,c as a,a5 as e}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Kế hoạch thay đổi Task/Approval — DB trước, ứng dụng sau","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/task-approval-simplification/plan.md","filePath":"feature/content-task-workflow/task-approval-simplification/plan.md"}'),h={name:"feature/content-task-workflow/task-approval-simplification/plan.md"};function o(r,t,l,c,s,g){return n(),a("div",null,[...t[0]||(t[0]=[e('<p>&gt; <strong>SUPERSEDED for new implementation — 2026-10-18:</strong> tài liệu này giữ lịch sử đề xuất ngày 16/10, không dùng làm checklist hiện hành hoặc lệnh APPLY. Xem <a href="./../3-6-9-approval-sequence-creator-manager-client/spec.html">spec FR3.6.9 v3</a>, <a href="./../3-6-9-approval-sequence-creator-manager-client/plan.html">plan</a>, <a href="./../3-6-9-approval-sequence-creator-manager-client/task.html">task</a>, <a href="./../3-6-9-approval-sequence-creator-manager-client/test.html">test</a>. Đã chốt /editor, một bản hiện tại không review snapshots, withdraw trước Manager decision và một Client bất kỳ. Task structure đã triển khai riêng; Approval mới hoàn thành tài liệu giai đoạn 1.</p><p>&gt; Checkpoint 2026-10-17 (historical): Task structure removal of QC/plannedPublishAt and Atlas metadata APPLY were implemented separately; earlier inventory/results below are dated history, not current-state evidence.</p><h1 id="ke-hoach-thay-đoi-task-approval-—-db-truoc-ung-dung-sau" tabindex="-1">Kế hoạch thay đổi Task/Approval — DB trước, ứng dụng sau <a class="header-anchor" href="#ke-hoach-thay-đoi-task-approval-—-db-truoc-ung-dung-sau" aria-label="Permalink to &quot;Kế hoạch thay đổi Task/Approval — DB trước, ứng dụng sau&quot;">​</a></h1><p>Ngày: 2026-10-16. <strong>Chờ review; không phải hướng dẫn chạy APPLY ngay.</strong> Đọc <a href="./spec.html">spec</a>, <a href="./task.html">checklist</a>, <a href="./test.html">test</a>.</p><h2 id="_1-muc-tieu-va-gioi-han-an-toan" tabindex="-1">1. Mục tiêu và giới hạn an toàn <a class="header-anchor" href="#_1-muc-tieu-va-gioi-han-an-toan" aria-label="Permalink to &quot;1. Mục tiêu và giới hạn an toàn&quot;">​</a></h2><p>Giữ bản demo ổn định, chuẩn bị schema tương thích cho BA bỏ QC/ngày đăng dự kiến. Không init/seed/xóa dữ liệu, không thay Content Writing/publishing, không thêm collection review round. Không chỉnh migration cũ đã merge. Không tự commit/push hoặc chạy migration theo tài liệu này.</p><h2 id="_2-baseline-đa-kiem-tra-tren-atlas-ngay-2026-10-16" tabindex="-1">2. Baseline đã kiểm tra trên Atlas ngày 2026-10-16 <a class="header-anchor" href="#_2-baseline-đa-kiem-tra-tren-atlas-ngay-2026-10-16" aria-label="Permalink to &quot;2. Baseline đã kiểm tra trên Atlas ngày 2026-10-16&quot;">​</a></h2><p>Đây là ảnh chụp kiểm kê, KHÔNG là số liệu để hardcode khi APPLY; phải kiểm tra lại.</p><table tabindex="0"><thead><tr><th>Collection</th><th>Kết quả kiểm tra</th></tr></thead><tbody><tr><td>tasks</td><td>14 Task, validator hỗ trợ canonical + legacy; 1 QC_REVIEW, 5 có qcAssigneeId, 1 IN_REVIEW thiếu reviewStep</td></tr><tr><td>task_approvals</td><td>0 bản ghi; action APPROVE/REJECT, step QC/MANAGER/CLIENT; có index đọc lịch sử nhưng chưa unique quyết định mỗi bước/lượt</td></tr><tr><td>posts</td><td>39 Post, 0 có task_id; validator legacy dùng platform trong khi code dùng target_platforms; validationAction=warn, 33 không khớp validator hiện tại</td></tr><tr><td>post_versions</td><td>Chưa có tại thời điểm kiểm kê; thuộc thiết kế snapshot/Admin hiện có, không tự thêm trong phạm vi đang hoãn</td></tr><tr><td>task_notification_outbox</td><td>Có schema/index, 0 bản ghi; eventType hiện TASK_ASSIGNED/TASK_COMMENTED</td></tr></tbody></table><p>Task/Request foundation và five-state migration đã được áp dụng trước đó; không chạy lại migration cũ để ghi đè validator mới.</p><h2 id="_3-giai-đoan-a-—-review-truoc-thay-đoi-db" tabindex="-1">3. Giai đoạn A — Review trước thay đổi DB <a class="header-anchor" href="#_3-giai-đoan-a-—-review-truoc-thay-đoi-db" aria-label="Permalink to &quot;3. Giai đoạn A — Review trước thay đổi DB&quot;">​</a></h2><ol><li>Chốt spec và các điểm mở; phân biệt nhận xét quyết định duyệt với thảo luận Task.</li><li>Đồng bộ BA/spec dùng chung sau review; không thay thế lịch sử bằng giả định mới.</li><li>Xác định writer/consumer: TaskWorkflowSchema/Service/DTO/UI còn đọc plannedPublishAt và QC; TaskNotificationWorker hiện xử lý giao việc theo Creator, chưa phù hợp người duyệt Manager/Client.</li><li>Chốt tên field nhận xét. reviewNote hiện là ĐỀ XUẤT, không phải contract đã triển khai.</li></ol><h2 id="_4-giai-đoan-b-—-inventory-thiet-ke-migration-tuong-thich" tabindex="-1">4. Giai đoạn B — Inventory + thiết kế migration tương thích <a class="header-anchor" href="#_4-giai-đoan-b-—-inventory-thiet-ke-migration-tuong-thich" aria-label="Permalink to &quot;4. Giai đoạn B — Inventory + thiết kế migration tương thích&quot;">​</a></h2><ul><li>Kiểm kê count, trạng thái, QC, ngày đăng dự kiến, approval trùng, missing round/revision/start evidence; chỉ xuất metadata/count hoặc allowlist cần review, không log token/nội dung nhạy cảm.</li><li>Không suy lịch sử firstStartedAt/By từ trạng thái; không tự liên kết Post với Task từ tiêu đề/tác giả.</li><li>Giữ validator của các field legacy để code đang chạy vẫn hoạt động. Đặc biệt TaskWorkflowSchema hiện yêu cầu property plannedPublishAt; xóa ngay sẽ gây TASK_SCHEMA_NOT_READY.</li><li>Giữ nguyên dueDate và workflowRevision, nguồn Campaign/Request, cancellation, index nền và lịch sử.</li><li>Unique quyết định: khóa taskId + approvalRound + step cho APPROVE/REJECT. Preflight dữ liệu/index hiện có; nếu chọn partial index phải thử đúng phiên bản Mongo trước. Không xóa/ghi đè duplicate để ép tạo index.</li><li>Nếu chốt reviewNote: bổ sung optional, giữ comment cũ; thiết kế reader ưu tiên reviewNote rồi fallback comment. Hai field có nội dung khác nhau phải báo để review, không tự ghi đè.</li><li>Có thể bổ sung posts.task_id optional + unique có điều kiện cho Post gắn Task sau khi contract liên kết được review. Không đổi posts.validationAction sang error, không làm sạch 33 Post ngoài scope. Link phải được kiểm tra cùng Workspace/đúng TaskType ở API.</li><li>Mở rộng enum notification theo event đã chốt nhưng giữ loại cũ; tên event cụ thể chốt cùng service/worker, schema một mình không bảo đảm giao thông báo.</li><li>Không thêm snapshot fields/collection hoặc SUBMIT/WITHDRAW events vào approval trong giai đoạn này.</li></ul><p>Các file mới dự kiến (tên cuối chốt lúc implementation):</p><table tabindex="0"><thead><tr><th>Migration đề xuất, CHƯA TẠO</th><th>Phạm vi</th></tr></thead><tbody><tr><td>task-approval-decisions-foundation.js</td><td>Field nhận xét nếu được chốt, index chống trùng quyết định</td></tr><tr><td>task-post-link.js</td><td>task_id optional/index, không auto-link dữ liệu cũ</td></tr><tr><td>task-review-notifications.js</td><td>Loại sự kiện duyệt bổ sung tương thích</td></tr><tr><td>task-review-legacy-reconciliation.js — riêng, chỉ sau duyệt allowlist</td><td>Task QC/thiếu bước duyệt; không tự chạy cùng schema migration</td></tr></tbody></table><p>Mỗi migration mới mặc định DRY_RUN, explicit APPLY, fail trước ghi khi conflict. Cập nhật cùng init-mongo.js, checker và tests. Không có thay đổi PostgreSQL dự kiến ở phạm vi này; kiểm tra lại khi review contract ứng dụng.</p><h2 id="_5-giai-đoan-c-—-rehearsal-va-apply-co-kiem-soat" tabindex="-1">5. Giai đoạn C — Rehearsal và APPLY có kiểm soát <a class="header-anchor" href="#_5-giai-đoan-c-—-rehearsal-va-apply-co-kiem-soat" aria-label="Permalink to &quot;5. Giai đoạn C — Rehearsal và APPLY có kiểm soát&quot;">​</a></h2><ol><li>Backup theo chính sách team; freeze mọi writer liên quan, không chỉ máy local nếu Atlas dùng chung.</li><li>Chạy cả chuỗi trên Mongo cô lập với metadata và dữ liệu bounded; thử writer cũ/mới và chạy lại.</li><li>Đối chiếu fingerprint/count/index, phát hiện thay đổi đồng thời hoặc duplicate thì dừng.</li><li>Chỉ APPLY Atlas khi operator duyệt và preflight sạch. DDL nhiều collection không atomic; nếu áp một phần phải khóa tính năng, kiểm kê và khôi phục metadata theo phương án đã review; không drop collection.</li><li>Xác minh không đổi tài liệu/content/Task cũ hoặc Post/Chat/Mail schemas ngoài phạm vi. Schema readiness phải pass với bản ứng dụng hiện tại.</li></ol><h2 id="_6-giai-đoan-d-—-code-ung-dung-lam-sau-review-db" tabindex="-1">6. Giai đoạn D — Code ứng dụng, làm sau review DB <a class="header-anchor" href="#_6-giai-đoan-d-—-code-ung-dung-lam-sau-review-db" aria-label="Permalink to &quot;6. Giai đoạn D — Code ứng dụng, làm sau review DB&quot;">​</a></h2><ul><li>Bỏ QC và plannedPublishAt khỏi UI/DTO/validation/schema guard; giữ dueDate/CAS/date bounds. Backend phải ngừng ghi field bỏ dùng.</li><li>Tạo/tìm đúng một Post theo Task; không đụng publishing. Các module content khác nối sau, chưa có integration thì không cho duyệt giả.</li><li>Submit/approve/reject/history theo round; role/scope/step/CAS trong transaction, reason bắt buộc reject, final approve FINISHED. Thứ tự tăng round ở lần gửi đầu/gửi lại phải nhất quán với mặc định approvalRound=1 hiện có.</li><li>Review nội dung/khóa sửa/phiên bản vẫn là checkpoint với Content Writing; không tuyên bố end-to-end an toàn khi chưa phối hợp.</li><li>Notification có outbox và phân quyền recipient Manager/Client/Creator theo event, giữ hành vi giao việc hiện có.</li><li>Thu hồi chưa code khi BA chưa chốt; chưa mở lại FINISHED.</li></ul><h2 id="_7-giai-đoan-e-—-cleanup-sau-khi-on-đinh" tabindex="-1">7. Giai đoạn E — Cleanup sau khi ổn định <a class="header-anchor" href="#_7-giai-đoan-e-—-cleanup-sau-khi-on-đinh" aria-label="Permalink to &quot;7. Giai đoạn E — Cleanup sau khi ổn định&quot;">​</a></h2><p>Chỉ sau khi writer mới triển khai và dữ liệu cũ được review, mới cân nhắc migration riêng để bỏ plannedPublishAt/QC/detailIdentified legacy. Không xóa bằng việc đơn thuần xóa field Java. Không xóa lịch sử approval. Việc thu hẹp enum phải preflight sạch và có kế hoạch tương thích/rollback.</p><h2 id="_8-ranh-gioi-ban-giao" tabindex="-1">8. Ranh giới bàn giao <a class="header-anchor" href="#_8-ranh-gioi-ban-giao" aria-label="Permalink to &quot;8. Ranh giới bàn giao&quot;">​</a></h2><ul><li>Phước/chủ Content Writing: nhận contract Task-content và điểm mở, không tự thay editor/Yjs/content versions.</li><li>Chủ publishing: không sửa status/queue/callback/xuất bản trong kế hoạch này.</li><li>Chủ module Livestream/Survey/Event: thống nhất nội dung bàn giao và API tích hợp riêng.</li><li>Tài liệu report không thuộc phạm vi yêu cầu; Jira/master plan không tự đổi assignee/Done.</li></ul>',25)])])}const p=i(h,[["render",o]]);export{u as __pageData,p as default};
